package br.com.tapeteskalke.service; import br.com.tapeteskalke.dto.UsuarioDtos.*; import br.com.tapeteskalke.entity.*; import br.com.tapeteskalke.exception.*; import br.com.tapeteskalke.repository.*; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class UsuarioService { private final UsuarioRepository users; private final CargoRepository cargos; private final PasswordEncoder encoder; private final AuditService audit; private final CurrentRole role; public UsuarioService(UsuarioRepository users,CargoRepository cargos,PasswordEncoder encoder,AuditService audit,CurrentRole role){this.users=users;this.cargos=cargos;this.encoder=encoder;this.audit=audit;this.role=role;}
 @Transactional(readOnly=true) public List<Response> list(){requireOwner();return users.listWithCargo().stream().map(this::response).toList();}
 @Transactional public Response create(CreateRequest r){requireOwner();var email=r.email().trim().toLowerCase();if(users.existsByEmailIgnoreCase(email))throw new BusinessException("EMAIL_DUPLICADO","Já existe usuário com este e-mail",HttpStatus.CONFLICT);var u=new Usuario();u.setNome(r.nome().trim());u.setEmail(email);u.setSenhaHash(encoder.encode(r.senha()));u.setCargo(cargo(r.cargo()));audit.created(u);return response(users.save(u));}
 @Transactional public Response update(String id,UpdateRequest r){requireOwner();var u=find(id);var novoCargo=cargo(r.cargo());boolean deixaDeSerDono="DONO".equals(u.getCargo().getCodigo())&&u.isAtivo()&&(!r.ativo()||!"DONO".equals(novoCargo.getCodigo()));if(deixaDeSerDono&&users.countActiveOwners()<=1)throw new BusinessException("SELF_LOCKOUT","O sistema precisa de ao menos um DONO ativo",HttpStatus.CONFLICT);u.setNome(r.nome().trim());u.setCargo(novoCargo);u.setAtivo(r.ativo());audit.changed(u);return response(u);}
 @Transactional public void resetSenha(String id,ResetSenhaRequest r){requireOwner();var u=find(id);u.setSenhaHash(encoder.encode(r.senha()));u.setSessaoVersao(u.getSessaoVersao()+1);audit.changed(u);}
 @Transactional public void trocarPropriaSenha(TrocarSenhaRequest r){var u=find(audit.userId());if(!encoder.matches(r.senhaAtual(),u.getSenhaHash()))throw new BusinessException("SENHA_ATUAL_INVALIDA","Senha atual incorreta",HttpStatus.UNPROCESSABLE_ENTITY);u.setSenhaHash(encoder.encode(r.novaSenha()));u.setSessaoVersao(u.getSessaoVersao()+1);audit.changed(u);}
 private void requireOwner(){if(!"DONO".equals(role.value()))throw new AccessDeniedBusinessException("Somente o dono pode gerenciar usuários");}
 private Usuario find(String id){return users.findById(id).orElseThrow(()->new ResourceNotFoundException("Usuário",id));}
 private Cargo cargo(String codigo){return cargos.findByCodigo(codigo).orElseThrow(()->new ResourceNotFoundException("Cargo",codigo));}
 private Response response(Usuario u){return new Response(u.getId(),u.getNome(),u.getEmail(),u.getCargo().getCodigo(),u.isAtivo());}
}
